const { Client, GatewayIntentBits } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

const { ApplicationCommandType, ApplicationCommandOptionType } = require('discord.js');

client.on('ready', () => {
  console.log('Bot is ready!');
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  if (interaction.commandName === 'ban') {
    if (!interaction.memberPermissions?.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'You don't have permission to ban members.',
        ephemeral: true,
      });
    }

    const member = interaction.options.getMember('user');
    if (!member) {
      return interaction.reply({
        content: 'Please provide a valid user to ban.',
        ephemeral: true,
      });
    }

    if (!member.bannable) {
      return interaction.reply({
        content: 'I can\'t ban this user.',
        ephemeral: true,
      });
    }

    await interaction.guild.bans.create(member.user.id);

    interaction.reply({
      content: `${member.user.tag} has been banned.`,
    });
  }
});

client.login(process.env.TOKEN);
```

5. Replace `process.env.TOKEN` with your Discord bot token.
6. Save the file.
7. Create a new folder named `commands` in the same directory as `index.js`.
8. Inside the `commands` folder, create a new JavaScript file named `ban.js`.
9. Copy and paste the following code into `ban.js`:

```javascript
