Here's an example implementation of a C++ function that takes a reference to a `std::string` containing Markdown formatted text and returns a `std::string` containing HTML formatted text using the [Pandoc](https://pandoc.org/) library:

```cpp
#include <iostream>
#include <string>
#include <pandoc/include/pandoc/pandoc.h>

std::string convertMarkdownToHtml(const std::string& markdown) {
    // Initialize Pandoc options
    PandocOptions options;
    options.input_format = "markdown";
    options.output_format = "html";
    options.output = "";

    // Convert Markdown to HTML
    std::string html;
    int ret = pandoc_convert(markdown.c_str(), &options, &html);
    if (ret != 0) {
        std::cerr << "Error converting Markdown to HTML: " << pandoc_get_error(options.error) << std::endl;
        return "";
    }

    return html;
}

int main() {
    std::string markdown = "This is some **bold** and *italic* text. A [link](https://example.com) and an image: ![alt text](https://example.com/image.png)";
    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
